-- Complete the rule inventory from Book 3 lesson 1 pages 4-18.
begin;
with extra (lesson_number, sort_order, title, summary, explanation, examples, irab) as (
  values
  ('1', 75, 'الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الْأَفْعَالِ (Изменяемые и неизменяемые глаголы)', 'Прошедшее и повелительное обычно неизменяемы, المضارع обычно изменяем.', 'Прошедшее время и повелительное наклонение являются مبنيّان. Настояще-будущее время является معرب, кроме форм с نون النسوة или نون التوكيد, которые становятся неизменяемыми.', '<li><span dir="rtl" lang="ar">كَتَبَ الطَّالِبُ</span> — студент написал.</li><li><span dir="rtl" lang="ar">اُكْتُبْ دَرْسَكَ</span> — напиши свой урок.</li><li><span dir="rtl" lang="ar">لَنْ يَكْتُبَ</span> — он не будет писать.</li>', '<span dir="rtl" lang="ar">يَكْتُبَ: فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِلَنْ وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ.</span>'),
  ('1', 76, 'عَلَامَاتُ إِعْرَابِ الْمُضَارِعِ (Признаки и‘раба настоящего времени)', 'Мудари‘ бывает в раф‘, насбе и джазме.', 'Основной признак раф‘ — дамма, насба — фатха, джазма — сукун. У пяти глаголов и слабых глаголов действуют вторичные признаки, поэтому окончание анализируется по форме.', '<li><span dir="rtl" lang="ar">يَكْتُبُ الطَّالِبُ</span> — студент пишет.</li><li><span dir="rtl" lang="ar">لَنْ يَكْتُبَ الطَّالِبُ</span> — студент не будет писать.</li><li><span dir="rtl" lang="ar">لَمْ يَكْتُبْ الطَّالِبُ</span> — студент не написал.</li>', '<span dir="rtl" lang="ar">يَكْتُبْ: مُضَارِعٌ مَجْزُومٌ بِلَمْ وَعَلَامَةُ جَزْمِهِ السُّكُونُ.</span>'),
  ('1', 77, 'الْأَفْعَالُ الْخَمْسَةُ (Пять глагольных форм)', 'Формы с ألف الاثنين, واو الجماعة и ياء المخاطبة имеют нун в раф‘.', 'Пять форм настоящего времени: يَفْعَلَانِ, تَفْعَلَانِ, يَفْعَلُونَ, تَفْعَلُونَ, تَفْعَلِينَ. В насбе и джазме نون удаляется.', '<li><span dir="rtl" lang="ar">هُمَا يَكْتُبَانِ</span> — они вдвоём пишут.</li><li><span dir="rtl" lang="ar">لَنْ تَكْتُبُوا</span> — вы не будете писать.</li><li><span dir="rtl" lang="ar">لَمْ تَكْتُبِي</span> — ты не написала.</li>', '<span dir="rtl" lang="ar">تَكْتُبُوا: مُضَارِعٌ مَنْصُوبٌ بِلَنْ وَعَلَامَةُ نَصْبِهِ حَذْفُ النُّونِ.</span>'),
  ('1', 78, 'الْفِعْلُ النَّاقِصُ (Глагол с конечной слабой буквой)', 'В конце слабого глагола признак джазма выражается удалением буквы.', 'У глаголов, оканчивающихся на و, ي или ا, конечная слабая буква может исчезать в джазме. В раф‘ и насбе признак бывает оценочным или выражается фатхой согласно типу глагола.', '<li><span dir="rtl" lang="ar">هُوَ يَدْعُو</span> — он призывает.</li><li><span dir="rtl" lang="ar">لَمْ يَدْعُ</span> — он не призвал.</li><li><span dir="rtl" lang="ar">لَنْ يَدْعُوَ</span> — он не будет призывать.</li>', '<span dir="rtl" lang="ar">يَدْعُ: مُضَارِعٌ مَجْزُومٌ بِلَمْ وَعَلَامَةُ جَزْمِهِ حَذْفُ حَرْفِ الْعِلَّةِ.</span>'),
  ('1', 79, 'الْفِعْلُ الْمُضَعَّفُ (Удвоенный глагол)', 'В удвоенном глаголе две последние корневые буквы сливаются в шадду.', 'При джазме удвоенного глагола конечная шадда сохраняется, а сукун оценивается на последнем корневом элементе. Разбор требует различать корень и фонетическое слияние двух одинаковых согласных.', '<li><span dir="rtl" lang="ar">يَمُدُّ الْمُعَلِّمُ الْقَلَمَ</span> — учитель протягивает ручку.</li><li><span dir="rtl" lang="ar">لَمْ يَمْدُدْ يَدَهُ</span> — он не протянул руку.</li><li><span dir="rtl" lang="ar">مُدَّ الْحَبْلُ</span> — верёвка была натянута.</li>', '<span dir="rtl" lang="ar">يَمْدُدْ: مُضَارِعٌ مَجْزُومٌ، وَعَلَامَةُ جَزْمِهِ السُّكُونُ عَلَى آخِرِهِ.</span>'),
  ('1', 80, 'الْمَرْفُوعَاتُ مِنَ الْأَسْمَاءِ (Имена в раф‘)', 'Подлежащее, заместитель подлежащего, мубтада и хабар получают раф‘.', 'К основным именным членам в раф‘ относятся فاعل, نائب فاعل, مبتدأ и خبر, а также имя كان и تابع к марфу‘. Конкретный показатель зависит от числа и типа имени.', '<li><span dir="rtl" lang="ar">جَاءَ الطَّالِبُ</span> — студент пришёл.</li><li><span dir="rtl" lang="ar">خُلِقَ الْإِنْسَانُ</span> — человек создан.</li><li><span dir="rtl" lang="ar">اللَّهُ غَفُورٌ</span> — Аллах Прощающий.</li>', '<span dir="rtl" lang="ar">الطَّالِبُ: فَاعِلٌ مَرْفُوعٌ بِالضَّمَّةِ، وَغَفُورٌ خَبَرٌ مَرْفُوعٌ.</span>'),
  ('1', 81, 'الْمَنْصُوبَاتُ مِنَ الْأَسْمَاءِ (Имена в насбе)', 'Объект, обстоятельство, الحال и другие члены получают насб.', 'К насб относятся مفعول به, مفعول فيه, مفعول لأجله, مفعول معه, مفعول مطلق, حال, تمييز, مستثنى и المنادى. Роль определяется отношением к управляющему слову.', '<li><span dir="rtl" lang="ar">قَرَأْتُ الدَّرْسَ</span> — я прочитал урок.</li><li><span dir="rtl" lang="ar">جَلَسْتُ أَمَامَ الْمُدَرِّسِ</span> — я сел перед преподавателем.</li><li><span dir="rtl" lang="ar">جَاءَ الطَّالِبُ مُبَكِّرًا</span> — студент пришёл рано.</li>', '<span dir="rtl" lang="ar">الدَّرْسَ: مَفْعُولٌ بِهِ مَنْصُوبٌ، مُبَكِّرًا: حَالٌ مَنْصُوبٌ.</span>'),
  ('1', 82, 'الْمَجْرُورَاتُ مِنَ الْأَسْمَاءِ (Имена в джарре)', 'Идафа и предлог вводят именную группу в джарре.', 'Имя становится маджруром после حرف جر или как второй член идафы. В цепочке идафы каждый последующий член определяется предыдущим, а падеж устанавливается локально.', '<li><span dir="rtl" lang="ar">ذَهَبْتُ إِلَى الْمَسْجِدِ</span> — я пошёл в мечеть.</li><li><span dir="rtl" lang="ar">كِتَابُ الطَّالِبِ جَدِيدٌ</span> — книга студента новая.</li><li><span dir="rtl" lang="ar">سَلَّمْتُ عَلَى مُدَرِّسِ اللُّغَةِ</span> — я поприветствовал преподавателя языка.</li>', '<span dir="rtl" lang="ar">الْمَسْجِدِ: اسْمٌ مَجْرُورٌ بِإِلَى، وَالطَّالِبِ مُضَافٌ إِلَيْهِ.</span>'),
  ('1', 83, 'النَّعْتُ (Согласованное определение)', 'Определение следует за определяемым словом и согласуется с ним.', 'Нат‘ согласуется с определяемым словом в определённости, роде, числе и падеже. Нарушение одного из четырёх признаков меняет синтаксическую связь.', '<li><span dir="rtl" lang="ar">جَاءَ الطَّالِبُ الْمُجْتَهِدُ</span> — пришёл прилежный студент.</li><li><span dir="rtl" lang="ar">رَأَيْتُ طَالِبَةً مُجْتَهِدَةً</span> — я увидел прилежную студентку.</li><li><span dir="rtl" lang="ar">مَرَرْتُ بِطُلَّابٍ مُجْتَهِدِينَ</span> — я прошёл мимо прилежных студентов.</li>', '<span dir="rtl" lang="ar">الْمُجْتَهِدُ: نَعْتٌ مَرْفُوعٌ تَابِعٌ لِلطَّالِبِ.</span>'),
  ('1', 84, 'التَّوْكِيدُ (Усиление)', 'Повтор или слово نفسه/كلّ подтверждает объём и отсутствие исключения.', 'Тавкид бывает لفظيّ через повторение и معنويّ через слова نَفْس, عَيْن, كُلّ, جَمِيع. Усиливающий элемент следует за подтверждаемым в падеже.', '<li><span dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُ نَفْسُهُ</span> — сам преподаватель пришёл.</li><li><span dir="rtl" lang="ar">حَضَرَ الطُّلَّابُ كُلُّهُمْ</span> — все студенты присутствовали.</li><li><span dir="rtl" lang="ar">قَرَأْتُ الْكِتَابَ كُلَّهُ</span> — я прочитал всю книгу.</li>', '<span dir="rtl" lang="ar">نَفْسُهُ: تَوْكِيدٌ مَرْفُوعٌ تَابِعٌ لِلْمُدَرِّسِ.</span>'),
  ('1', 85, 'الْعَطْفُ (Сочинение)', 'Союз соединяет равноправные элементы и не меняет их синтаксическую роль.', 'При عطف النسق второй элемент следует за союзом и получает тот же падеж, что и первый. Значение связи определяется конкретным союзом: و, ف, ثم, أو и другими.', '<li><span dir="rtl" lang="ar">جَاءَ حَامِدٌ وَمُعَاوِيَةُ</span> — пришли Хамид и Муавия.</li><li><span dir="rtl" lang="ar">قَرَأْتُ وَكَتَبْتُ</span> — я прочитал и написал.</li><li><span dir="rtl" lang="ar">سَافِرْ أَوِ ابْقَ</span> — путешествуй или останься.</li>', '<span dir="rtl" lang="ar">مُعَاوِيَةُ: مَعْطُوفٌ مَرْفُوعٌ عَلَى حَامِدٍ.</span>'),
  ('1', 86, 'الْبَدَلُ (Замещение и пояснение)', 'Второе имя поясняет первое и принимает его падеж.', 'Бадаль следует за заменяемым словом и может обозначать его целиком, часть или связанное с ним содержание. В отличие от простого определения, он сам способен заменить первый член в предложении.', '<li><span dir="rtl" lang="ar">جَاءَ أَخُوكَ هَاشِمٌ</span> — пришёл твой брат Хашим.</li><li><span dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَ هَاشِمًا</span> — я увидел студента Хашима.</li><li><span dir="rtl" lang="ar">مَرَرْتُ بِأَخِيكَ هَاشِمٍ</span> — я прошёл мимо твоего брата Хашима.</li>', '<span dir="rtl" lang="ar">هَاشِمٌ: بَدَلٌ مَرْفُوعٌ مِنْ أَخُوكَ، وَيَتْبَعُهُ فِي الْإِعْرَابِ.</span>')
)
insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary)
select 'Мединский курс (Том 3)', lesson_number, title,
  '<p><strong>Академическое объяснение.</strong> ' || explanation || '</p><p><strong>Три примера.</strong></p><ol>' || examples || '</ol><p><strong>Полный разбор إِعْرَاب.</strong><br>' || irab || '</p>',
  sort_order, 'rule', summary
from extra;
commit;
